WITH session_stats AS (SELECT session_id, SUM(CASE WHEN page = '/checkout' THEN duration_sec ELSE 0 END) AS checkout_duration_sec, MIN(event_time) AS min_event_time FROM web_events WHERE event_time < '2023-04-01' GROUP BY session_id) SELECT s.browser, s.device, ss.checkout_duration_sec, ss.min_event_time FROM sessions s INNER JOIN session_stats ss ON s.id = ss.session_id ORDER BY device DESC, s.browser
